    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int i = 0;
    int len = str.length();
    while (i < len) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i >= len) {
                throw new Exception("Invalid escape sequence at the end of the string");
            }
            char nextChar = str.charAt(i);
            switch (nextChar) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
        } else {
            sb.append(c);
        }
        i++;
    }
    return sb.toString();
}

